// Expo config plugin: production concerns for the generated android/ project.
//
// The android/ directory is generated by `expo prebuild` and never committed,
// so anything we need in app/build.gradle has to be re-applied on every
// prebuild. This plugin does two things there:
//
// 1. Release signing. If android/keystore.properties exists (CI writes it from
//    encrypted secrets; see docs/ci-cd.md) the release build is signed with
//    that upload key. Without it the release build falls back to the debug
//    key, exactly like the Expo template — so a dry run on a machine with no
//    secrets still completes, and the pipeline labels those files UNSIGNED.
//
// 2. Enough memory for a release build. The template caps Gradle at 512 MB of
//    metaspace, which an R8-minified release of this app exceeds.
//
// 3. Per-ABI APK splits, opt-in with `-PsplitApks`. App bundles (.aab) ignore
//    splits; the store does per-device delivery itself. Split APKs are for
//    sideloading, where a 4-architecture universal APK is needlessly large.
const { withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

const GRADLE_JVM_ARGS = '-Xmx4g -XX:MaxMetaspaceSize=1g -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8';

const MARKER = '// @gridlock/release-signing';

const SIGNING_PROPS = `${MARKER}
def gridlockKeystoreProps = new Properties()
def gridlockKeystoreFile = rootProject.file('keystore.properties')
if (gridlockKeystoreFile.exists()) {
    gridlockKeystoreFile.withInputStream { gridlockKeystoreProps.load(it) }
}
def gridlockHasUploadKey = gridlockKeystoreProps['storeFile'] != null
`;

const RELEASE_SIGNING_CONFIG = `
        release {
            if (gridlockHasUploadKey) {
                storeFile file(gridlockKeystoreProps['storeFile'])
                storePassword gridlockKeystoreProps['storePassword']
                keyAlias gridlockKeystoreProps['keyAlias']
                keyPassword gridlockKeystoreProps['keyPassword']
            }
        }`;

const SPLITS = `
    splits {
        abi {
            enable project.hasProperty('splitApks')
            reset()
            include 'armeabi-v7a', 'arm64-v8a', 'x86', 'x86_64'
            universalApk true
        }
    }`;

function applyReleaseConfig(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // properties loader, before the android { } block
  gradle = gradle.replace(/^android \{/m, `${SIGNING_PROPS}\nandroid {`);

  // a `release` signing config next to the template's `debug` one
  gradle = gradle.replace(
    /signingConfigs \{\n(\s+)debug \{[\s\S]*?\n\1\}/,
    (block) => `${block}${RELEASE_SIGNING_CONFIG}`,
  );

  // release build type: upload key when present, debug key otherwise
  const releaseBlock = /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseBlock.test(gradle)) {
    throw new Error('[with-android-release] could not find the release signingConfig in app/build.gradle');
  }
  gradle = gradle.replace(
    releaseBlock,
    '$1signingConfig gridlockHasUploadKey ? signingConfigs.release : signingConfigs.debug',
  );

  // ABI splits, inside android { } right before buildTypes
  gradle = gradle.replace(/\n(\s+)buildTypes \{/, `${SPLITS}\n$1buildTypes {`);
  return gradle;
}

function withReleaseMemory(config) {
  return withGradleProperties(config, (cfg) => {
    const props = cfg.modResults.filter((p) => !(p.type === 'property' && p.key === 'org.gradle.jvmargs'));
    props.push({ type: 'property', key: 'org.gradle.jvmargs', value: GRADLE_JVM_ARGS });
    cfg.modResults = props;
    return cfg;
  });
}

module.exports = function withAndroidRelease(config) {
  config = withReleaseMemory(config);
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('[with-android-release] expected a Groovy app/build.gradle');
    }
    cfg.modResults.contents = applyReleaseConfig(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.applyReleaseConfig = applyReleaseConfig;
